"""Module dependency composition.

``DependencyGraph`` owns the call/pipe prerequisite edges of a campaign and
produces the documented plan order: prerequisites precede dependents and,
among the currently eligible modules, the lexicographically smallest name is
emitted first.  It also composes transitive pipe applications, so a filter's
own pipes are applied with the composed bindings of its application.
"""

from heapq import heapify, heappop, heappush


class DependencyError(Exception):
    """Raised when the dependency graph cannot be ordered."""


class DependencyGraph(object):
    """Directed prerequisite graph over module names."""

    def __init__(self):
        self.graph = {}
        self.dependencies = {}
        self.nodes = 0
        self.names = []

    def add_node(self, model):
        """Create a node for ``model`` if it does not exist yet."""
        if model not in self.graph:
            self.graph[model] = set()
            self.dependencies[model] = set()
            self.names.append(model)
            self.nodes += 1
        return model

    def add_edge(self, dependent, prerequisite):
        """Record that ``dependent`` needs ``prerequisite`` before it."""
        self.add_node(dependent)
        self.add_node(prerequisite)
        self.graph[dependent].add(prerequisite)
        self.dependencies[prerequisite].add(dependent)

    def Edge(self, model1, model2):
        """Adds a directed prerequisite edge ``model1 -> model2``."""
        self.add_edge(model1, model2)

    def CallEdge(self, model, dependency_models):
        """Adds prerequisite edges from ``model`` to each dependency."""
        for dependency in dependency_models:
            self.add_edge(model, dependency)

    def Pipe(self, model1, model2):
        """Adds a pipe prerequisite: the target needs its filter first."""
        self.add_edge(model1, model2)

    def Node(self, model):
        """Creates a new node in the dependency graph."""
        return self.add_node(model)

    def topologicalSort(self):
        """Prerequisite-first order of every node, lexicographically stable."""
        order = []
        remaining = {name: len(self.graph[name]) for name in self.graph}
        heap = [name for name in self.graph if remaining[name] == 0]
        heapify(heap)
        while heap:
            name = heappop(heap)
            order.append(name)
            for dependent in self.dependencies[name]:
                remaining[dependent] -= 1
                if remaining[dependent] == 0:
                    heappush(heap, dependent)
        if len(order) != len(self.graph):
            raise DependencyError('dependency cycle detected')
        return order

    def compile_order(self, root):
        """Root-scoped compilation order used by the certificate plans.

        The result contains ``root`` and every transitive prerequisite,
        prerequisites before dependents, taking the lexicographically
        smallest eligible module first.
        """
        subgraph = set()
        stack = [root]
        while stack:
            name = stack.pop()
            if name in subgraph:
                continue
            if name not in self.graph:
                raise DependencyError('unknown module ' + str(name))
            subgraph.add(name)
            stack.extend(self.graph[name])
        remaining = {name: len(self.graph[name]) for name in subgraph}
        heap = [name for name in subgraph if remaining[name] == 0]
        heapify(heap)
        order = []
        while heap:
            name = heappop(heap)
            order.append(name)
            for dependent in self.dependencies[name]:
                if dependent in subgraph:
                    remaining[dependent] -= 1
                    if remaining[dependent] == 0:
                        heappush(heap, dependent)
        if len(order) != len(subgraph):
            raise DependencyError('dependency cycle detected')
        return order


class Application(object):
    """One composed pipe application over an entry's own parameters.

    ``module`` is the applied filter, ``mapping`` resolves each of its
    parameters to an entry parameter name, and ``children`` are the filter's
    own composed pipe applications.
    """

    __slots__ = ('module', 'mapping', 'children')

    def __init__(self, module, mapping, children):
        self.module = module
        self.mapping = mapping
        self.children = children

    def accepts(self, values, evaluator):
        """Acceptance is the filter's own predicate AND its bound filters."""
        requirement = self.module.requirement
        if requirement is not None:
            environment = {}
            for parameter, source in self.mapping.items():
                try:
                    environment[parameter] = values[source]
                except KeyError:
                    raise DependencyError(
                        'unbound filter parameter ' + str(parameter))
            if not evaluator(requirement, environment):
                return False
        for child in self.children:
            if not child.accepts(values, evaluator):
                return False
        return True


def compose(target, pipes_of):
    """Compose the pipe applications of ``target``.

    ``pipes_of(module)`` yields that module's own pipes in order; each pipe
    exposes ``filter`` (the applied module) and ``bind`` (a mapping from the
    applied filter's parameters to the target's parameters).
    """
    applications = []
    for pipe in pipes_of(target):
        applications.append(_compose(pipe.filter, pipe.bind, pipes_of, 0))
    return applications


def _compose(module, mapping, pipes_of, depth):
    if depth > 64:
        raise DependencyError('pipe composition too deep')
    children = []
    for pipe in pipes_of(module):
        composed = {}
        for parameter, source in pipe.bind.items():
            if source not in mapping:
                raise DependencyError(
                    'pipe binding refers to an unknown parameter '
                    + str(source))
            composed[parameter] = mapping[source]
        children.append(_compose(pipe.filter, composed, pipes_of, depth + 1))
    return Application(module, mapping, children)
