"""Strict binary symbolic-test transport (KTEST v3).

Layout: ASCII ``KTEST``, big-endian uint32 version 3, uint32 argument count
followed by that many length-prefixed blobs, uint32 symbolic-argv count and
length, uint32 object count, then object name blob / data blob pairs.  No
trailing byte is allowed and object names are canonical ``x`` plus a decimal
integer without leading zeros.
"""

import base64
import binascii

_MAGIC = b'KTEST'
_VERSION = 3
_MAX_ARGUMENTS = 64
_MAX_ARGUMENT_BYTES = 256


class TransportError(Exception):
    """Raised for any base64, binary or inventory framing error."""


def _object_name(raw):
    try:
        name = raw.decode('ascii')
    except UnicodeDecodeError:
        raise TransportError('object name is not ASCII')
    if not name.startswith('x') or len(name) < 2:
        raise TransportError('malformed object name')
    digits = name[1:]
    if not digits.isdigit() or not digits.isascii():
        raise TransportError('malformed object name')
    if len(digits) > 1 and digits[0] == '0':
        raise TransportError('object name has a leading zero')
    return name


def parse(raw):
    """Parse a decoded KTEST payload into an ordered object mapping."""
    if not isinstance(raw, (bytes, bytearray, memoryview)):
        raise TransportError('payload must be binary')
    data = bytes(raw)
    size = len(data)
    offset = 0

    def take(count):
        nonlocal offset
        if count < 0 or offset + count > size:
            raise TransportError('truncated payload')
        blob = data[offset:offset + count]
        offset += count
        return blob

    def u32():
        return int.from_bytes(take(4), 'big')

    if take(5) != _MAGIC:
        raise TransportError('bad magic')
    if u32() != _VERSION:
        raise TransportError('unsupported version')
    arguments = u32()
    if arguments > _MAX_ARGUMENTS:
        raise TransportError('too many arguments')
    for _ in range(arguments):
        length = u32()
        if length > _MAX_ARGUMENT_BYTES:
            raise TransportError('argument too large')
        take(length)
    take(4)
    take(4)
    count = u32()
    objects = {}
    for _ in range(count):
        length = u32()
        name = _object_name(take(length))
        if name in objects:
            raise TransportError('duplicate object ' + name)
        objects[name] = take(u32())
    if offset != size:
        raise TransportError('trailing bytes')
    return objects


def decode(payload):
    """Decode a standard base64 KTEST string into its object inventory."""
    if not isinstance(payload, str):
        raise TransportError('payload must be a string')
    try:
        raw = base64.b64decode(payload.encode('ascii'), validate=True)
    except (binascii.Error, ValueError, UnicodeEncodeError):
        raise TransportError('malformed base64')
    return parse(raw)


#: Descriptive alias used by the pipeline.
decode_ktest = decode
